import { useContext } from 'react';
import { useNavigate } from 'react-router-dom';
import { AuthContext } from '../../context/authContext';
import { DarkModeContext } from '../../context/darkModeContext';
import './leftBar.scss';

const LeftBar = () => {
  const { currentUser } = useContext(AuthContext);
  const { toggle, darkMode } = useContext(DarkModeContext);
  const navigate = useNavigate();

  return (
    <div className={`leftBar ${darkMode ? 'theme-dark' : 'theme-light'}`}>
      <div className="container">
        <div className="menu">
          <div className="user">
            <img
              src={currentUser?.profilePicture || '/default-avatar.png'}
              alt="Profile"
            />
            <span>{currentUser?.username}</span>
          </div>
          <div className="item" onClick={() => navigate('/')}>
            <span>Home</span>
          </div>
          <div className="item" onClick={() => navigate(`/profile/${currentUser?._id}`)}>
            <span>Profile</span>
          </div>
          <div className="item" onClick={() => navigate('/friends')}>
            <span>Friends</span>
          </div>
          <div className="item" onClick={() => navigate('/messages')}>
            <span>Messages</span>
          </div>
          <div className="item" onClick={() => navigate('/add-friends')}>
            <span>Add Friends</span>
          </div>
          <div className="item" onClick={() => navigate('/notifications')}>
            <span>Notifications</span>
          </div>
          <div className="item" onClick={toggle}>
            <span>{darkMode ? 'Light Mode' : 'Dark Mode'}</span>
          </div>
          {currentUser && (
            <div className="item" onClick={() => {
              localStorage.removeItem('token');
              localStorage.removeItem('user');
              navigate('/login');
            }}>
              <span>Logout</span>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default LeftBar;
